def max_edges_girth_7(n):
    from pysat.solvers import Glucose3
    from pysat.formula import WCNF
    import itertools

    def solve_k_edges(k):
        solver = Glucose3()

        # Variables for edges
        def var(i, j):
            if i > j: i, j = j, i
            return i * n + j + 1

        # Girth >= 7
        # 3-cycles
        for i, j, l in itertools.combinations(range(n), 3):
            solver.add_clause([-var(i, j), -var(j, l), -var(l, i)])

        # 4-cycles
        for c in itertools.combinations(range(n), 4):
            for p in itertools.permutations(c):
                if p[0] == min(p) and p[1] < p[3]:
                    solver.add_clause([-var(p[0], p[1]), -var(p[1], p[2]), -var(p[2], p[3]), -var(p[3], p[0])])

        # 5-cycles
        for c in itertools.combinations(range(n), 5):
            for p in itertools.permutations(c):
                if p[0] == min(p) and p[1] < p[4]:
                    solver.add_clause([-var(p[0], p[1]), -var(p[1], p[2]), -var(p[2], p[3]), -var(p[3], p[4]), -var(p[4], p[0])])

        # 6-cycles
        for c in itertools.combinations(range(n), 6):
            for p in itertools.permutations(c):
                if p[0] == min(p) and p[1] < p[5]:
                    solver.add_clause([-var(p[0], p[1]), -var(p[1], p[2]), -var(p[2], p[3]), -var(p[3], p[4]), -var(p[4], p[5]), -var(p[5], p[0])])

        # At least k edges
        from pysat.card import CardEnc
        edges = [var(i, j) for i in range(n) for j in range(i+1, n)]
        cnf = CardEnc.atleast(lits=edges, bound=k, encoding=1)
        for clause in cnf.clauses:
            solver.add_clause(clause)

        return solver.solve()

    # Binary search for max edges
    low = 0
    high = n * (n - 1) // 2
    best = 0
    while low <= high:
        mid = (low + high) // 2
        print(f"Testing {mid} edges...")
        if solve_k_edges(mid):
            best = mid
            low = mid + 1
        else:
            high = mid - 1
    return best

